'use client';

import { useEffect, useRef } from 'react';

export default function About() {
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.querySelectorAll('.fade-in').forEach((el) => {
              el.classList.add('visible');
            });
          }
        });
      },
      { threshold: 0.15 }
    );
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <section id="about" className="about" ref={sectionRef} aria-label="About section">
      <div className="container">
        <div className="about-grid">
          {/* Image side */}
          <div className="about-image-wrapper fade-in">
            <div className="about-image-accent" aria-hidden="true" />
            <div className="about-image-frame">
              {/* Placeholder — replace with <Image> when oyage image ready */}
              <div
                style={{
                  width: '100%',
                  height: '100%',
                  background: 'linear-gradient(160deg, #1a120a 0%, #2e1f10 40%, #0f0a06 100%)',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '1rem',
                  minHeight: '500px',
                }}
              >
                <div style={{ fontSize: '6rem', opacity: 0.3 }}>📸</div>
                <p style={{ color: 'var(--color-gold)', opacity: 0.5, fontSize: '0.75rem', letterSpacing: '0.2em', textTransform: 'uppercase' }}>
                  Your Photo Here
                </p>
              </div>
            </div>
            <div className="about-image-badge" aria-label="5 star rating">
              <div className="about-badge-number">5★</div>
              <div className="about-badge-text">Rated</div>
            </div>
          </div>

          {/* Content side */}
          <div className="about-content">
            <div className="fade-in">
              <div className="section-label">About Me</div>
              <h2 className="section-title">
                The Artist Behind<br />the <em>Lens</em>
              </h2>
            </div>

            <p className="about-bio fade-in fade-in-delay-1">
              Hello! I'm <strong>Tharu</strong>, a passionate photographer based in Sri Lanka with over
              8 years of experience capturing the raw beauty of life. From intimate
              wedding moments to breathtaking landscapes, I believe every photograph
              should evoke genuine emotion.
            </p>

            <p className="about-bio fade-in fade-in-delay-2">
              My approach blends <strong>technical precision</strong> with an artistic eye —
              always chasing the perfect light, the unguarded smile, the fleeting
              moment that tells a thousand words.
            </p>

            <div className="about-stats fade-in fade-in-delay-2">
              {[
                { number: '500+', label: 'Sessions' },
                { number: '8+',   label: 'Years' },
                { number: '12',   label: 'Awards' },
              ].map((s) => (
                <div key={s.label}>
                  <div className="about-stat-number">{s.number}</div>
                  <div className="about-stat-label">{s.label}</div>
                </div>
              ))}
            </div>

            <div className="about-signature fade-in fade-in-delay-3">Tharu</div>
          </div>
        </div>
      </div>
    </section>
  );
}
