'use client';

import { useEffect, useRef } from 'react';

export default function Hero() {
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = contentRef.current;
    if (el) {
      el.querySelectorAll('.fade-in').forEach((node, i) => {
        setTimeout(() => {
          node.classList.add('visible');
        }, i * 150);
      });
    }
  }, []);

  const scrollToGallery = (e: React.MouseEvent) => {
    e.preventDefault();
    document.querySelector('#gallery')?.scrollIntoView({ behavior: 'smooth' });
  };

  const scrollToContact = (e: React.MouseEvent) => {
    e.preventDefault();
    document.querySelector('#contact')?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <section id="hero" className="hero" aria-label="Hero section">
      {/* Background */}
      <div className="hero-bg" />

      {/* Decorative gradient blobs */}
      <div
        style={{
          position: 'absolute',
          top: '20%',
          right: '15%',
          width: '400px',
          height: '400px',
          background: 'radial-gradient(circle, rgba(201,169,110,0.08) 0%, transparent 70%)',
          borderRadius: '50%',
          pointerEvents: 'none',
          zIndex: 2,
        }}
      />
      <div
        style={{
          position: 'absolute',
          bottom: '25%',
          left: '5%',
          width: '300px',
          height: '300px',
          background: 'radial-gradient(circle, rgba(201,169,110,0.05) 0%, transparent 70%)',
          borderRadius: '50%',
          pointerEvents: 'none',
          zIndex: 2,
        }}
      />

      <div className="hero-overlay" />
      <div className="hero-overlay-bottom" />

      {/* Main content */}
      <div className="container" style={{ width: '100%', position: 'relative', zIndex: 4 }}>
        <div className="hero-content" ref={contentRef}>
          {/* Eyebrow */}
          <div className="hero-eyebrow fade-in">
            <div className="hero-eyebrow-line" />
            <span className="hero-eyebrow-text">Professional Photography</span>
          </div>

          {/* Title */}
          <h1 className="hero-title fade-in fade-in-delay-1">
            Capturing Your
            <em>Perfect Moments</em>
          </h1>

          {/* Subtitle */}
          <p className="hero-subtitle fade-in fade-in-delay-2">
            Every frame tells a story. We craft timeless imagery that preserves
            the emotions, beauty, and authenticity of life's most treasured moments.
          </p>

          {/* CTA Buttons */}
          <div className="hero-actions fade-in fade-in-delay-3">
            <a
              href="#gallery"
              className="btn-primary"
              id="hero-view-portfolio-btn"
              onClick={scrollToGallery}
            >
              <span>✦</span> View Portfolio
            </a>
            <a
              href="#contact"
              className="btn-secondary"
              id="hero-book-session-btn"
              onClick={scrollToContact}
            >
              Book a Session →
            </a>
          </div>
        </div>
      </div>

      {/* Right-side stats */}
      <div className="container" style={{ position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 4 }}>
        <div className="hero-stats" style={{ pointerEvents: 'all' }}>
          {[
            { number: '500+', label: 'Sessions Done' },
            { number: '8 Yrs', label: 'Experience' },
            { number: '98%', label: 'Happy Clients' },
          ].map((stat) => (
            <div key={stat.label}>
              <div className="hero-stat-number">{stat.number}</div>
              <div className="hero-stat-label">{stat.label}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Scroll indicator */}
      <div className="hero-scroll-indicator" aria-hidden="true">
        <div className="hero-scroll-line" />
        <span>Scroll</span>
      </div>
    </section>
  );
}
