'use client';

import { useState, useCallback } from 'react';
import Lightbox from './Lightbox';

type Category = 'All' | 'Weddings' | 'Portraits' | 'Nature' | 'Events';

interface GalleryItem {
  id: number;
  title: string;
  category: Exclude<Category, 'All'>;
  emoji: string;
  bgClass: string;
  imagePath?: string;
}

const GALLERY_ITEMS: GalleryItem[] = [
  { id: 1,  title: 'Golden Vows',          category: 'Weddings',  emoji: '💍', bgClass: 'wedding'  },
  { id: 2,  title: 'Enchanted Garden',     category: 'Weddings',  emoji: '💒', bgClass: 'wedding'  },
  { id: 3,  title: 'Natural Elegance',     category: 'Portraits', emoji: '👤', bgClass: 'portrait' },
  { id: 4,  title: 'Misty Peaks',          category: 'Nature',    emoji: '🏔️', bgClass: 'nature'   },
  { id: 5,  title: 'Studio Soul',          category: 'Portraits', emoji: '🎭', bgClass: 'portrait' },
  { id: 6,  title: 'Starlight Gala',       category: 'Events',    emoji: '✨', bgClass: 'event'    },
  { id: 7,  title: 'Sacred Sunset',        category: 'Weddings',  emoji: '🌅', bgClass: 'wedding'  },
  { id: 8,  title: 'Forest Dreams',        category: 'Nature',    emoji: '🌿', bgClass: 'nature'   },
  { id: 9,  title: 'The Grand Occasion',   category: 'Events',    emoji: '🎉', bgClass: 'event'    },
];

const CATEGORIES: Category[] = ['All', 'Weddings', 'Portraits', 'Nature', 'Events'];

export default function Gallery() {
  const [activeFilter, setActiveFilter] = useState<Category>('All');
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);

  const filtered = activeFilter === 'All'
    ? GALLERY_ITEMS
    : GALLERY_ITEMS.filter((item) => item.category === activeFilter);

  const openLightbox = useCallback((idx: number) => setLightboxIndex(idx), []);
  const closeLightbox = useCallback(() => setLightboxIndex(null), []);
  const prevItem = useCallback(() => {
    setLightboxIndex((i) => (i === null ? null : (i - 1 + filtered.length) % filtered.length));
  }, [filtered.length]);
  const nextItem = useCallback(() => {
    setLightboxIndex((i) => (i === null ? null : (i + 1) % filtered.length));
  }, [filtered.length]);

  return (
    <section id="gallery" className="gallery" aria-label="Photography portfolio gallery">
      <div className="container">
        {/* Header */}
        <div className="gallery-header">
          <div>
            <div className="section-label">Portfolio</div>
            <h2 className="section-title">Selected <em>Works</em></h2>
          </div>

          {/* Filters */}
          <div className="gallery-filters" role="group" aria-label="Gallery filters">
            {CATEGORIES.map((cat) => (
              <button
                key={cat}
                className={`gallery-filter-btn${activeFilter === cat ? ' active' : ''}`}
                onClick={() => setActiveFilter(cat)}
                id={`gallery-filter-${cat.toLowerCase()}`}
                aria-pressed={activeFilter === cat}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Grid */}
        <div className="gallery-grid" role="list" aria-label="Gallery images">
          {filtered.map((item, idx) => (
            <div
              key={item.id}
              className={`gallery-item ${item.bgClass}`}
              role="listitem"
              tabIndex={0}
              aria-label={`${item.title} — ${item.category}`}
              onClick={() => openLightbox(idx)}
              onKeyDown={(e) => e.key === 'Enter' && openLightbox(idx)}
            >
              {/* Placeholder — swap this div for <Image> when you add real photos */}
              {item.imagePath ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img src={item.imagePath} alt={item.title} />
              ) : (
                <div className="gallery-placeholder" aria-hidden="true">
                  {item.emoji}
                </div>
              )}

              <div className="gallery-item-overlay">
                <div className="gallery-item-title">{item.title}</div>
                <div className="gallery-item-category">{item.category}</div>
              </div>
              <div className="gallery-item-icon" aria-hidden="true">⤢</div>
            </div>
          ))}
        </div>
      </div>

      {/* Lightbox */}
      {lightboxIndex !== null && (
        <Lightbox
          item={filtered[lightboxIndex]}
          onClose={closeLightbox}
          onPrev={prevItem}
          onNext={nextItem}
        />
      )}
    </section>
  );
}
