'use client';

import { useEffect, useRef } from 'react';

const SERVICES = [
  {
    id: 'wedding',
    icon: '💍',
    title: 'Wedding Photography',
    desc: 'Your wedding day deserves more than just photos — it deserves art. We capture every tear, every laugh, and every loving glance with cinematic precision.',
    features: ['Full-day coverage', 'Edited high-res gallery', 'Album design included', 'Engagement shoot'],
    price: 'LKR 85,000',
    unit: '/ day',
  },
  {
    id: 'portrait',
    icon: '🎭',
    title: 'Portrait Sessions',
    desc: 'Professional portraits that reveal your true character. Whether for personal branding, family memories, or artistic expression — we make you look extraordinary.',
    features: ['2-hour session', '50+ edited images', 'Multiple outfits', 'Studio or outdoor'],
    price: 'LKR 25,000',
    unit: '/ session',
  },
  {
    id: 'nature',
    icon: '🌿',
    title: 'Nature & Landscape',
    desc: "Sri Lanka's breathtaking landscapes, wildlife, and natural beauty — captured in stunning detail. From misty mountains to golden coastlines.",
    features: ['Sunrise & sunset shoots', 'Print-ready resolution', 'Commercial licensing', 'Remote locations'],
    price: 'LKR 35,000',
    unit: '/ day',
  },
  {
    id: 'event',
    icon: '✨',
    title: 'Events & Corporate',
    desc: 'From glamorous galas to product launches, we document your events with professionalism and style, ensuring every key moment is preserved.',
    features: ['Full event coverage', 'Same-day previews', 'Multi-camera setups', 'Rapid turnaround'],
    price: 'LKR 45,000',
    unit: '/ event',
  },
];

export default function Services() {
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.querySelectorAll('.fade-in').forEach((el) => el.classList.add('visible'));
          }
        });
      },
      { threshold: 0.1 }
    );
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <section id="services" className="services" ref={sectionRef} aria-label="Photography services">
      <div className="container">
        <div className="fade-in" style={{ textAlign: 'center', marginBottom: '1rem' }}>
          <div className="section-label" style={{ justifyContent: 'center' }}>What I Offer</div>
          <h2 className="section-title" style={{ textAlign: 'center' }}>
            Photography <em>Services</em>
          </h2>
        </div>
        <p
          className="fade-in fade-in-delay-1"
          style={{
            textAlign: 'center',
            color: 'var(--color-text-muted)',
            maxWidth: '550px',
            margin: '0 auto 1rem',
            fontSize: '0.95rem',
          }}
        >
          Tailored packages for every occasion — because your memories deserve the very best.
        </p>

        <div className="services-grid">
          {SERVICES.map((svc, i) => (
            <div
              key={svc.id}
              className={`service-card fade-in fade-in-delay-${i + 1}`}
              id={`service-card-${svc.id}`}
            >
              <div className="service-icon" aria-hidden="true">{svc.icon}</div>
              <h3 className="service-title">{svc.title}</h3>
              <p className="service-desc">{svc.desc}</p>
              <ul className="service-features" aria-label={`${svc.title} features`}>
                {svc.features.map((f) => <li key={f}>{f}</li>)}
              </ul>
              <div className="service-price">
                <span className="service-price-from">from</span>
                <span className="service-price-value">{svc.price}</span>
                <span className="service-price-unit">{svc.unit}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
